/* ============================================================
   DICTIONARY OF THE KHAZARS — по роману Милорада Павича
   Ночной Каспий, хазарская крепость, луна в дымке, среди звёзд
   еле видны забытые буквы. Каждый ответ персонажа — статья одной
   из трёх книг словаря (Красной, Зелёной или Жёлтой): своё
   заглавное слово, цвет корешка и вкладка-указатель с буквой.
   Пока персонаж отвечает, над полем ввода поднимаются и тают
   буквы — принцесса Атех забывает свой язык.
   Шрифт Alegreya (SIL OFL 1.1) встроен в тему.
   Нужен Advanced Rendering.
   ============================================================ */

@font-face {
  font-family: "Alegreya";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("theme/assets/alegreya-normal-400-cyrillic.woff2") format("woff2");
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
}
@font-face {
  font-family: "Alegreya";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("theme/assets/alegreya-normal-400-latin.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
@font-face {
  font-family: "Alegreya";
  font-style: italic;
  font-weight: 400;
  font-display: swap;
  src: url("theme/assets/alegreya-italic-400-cyrillic.woff2") format("woff2");
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
}
@font-face {
  font-family: "Alegreya";
  font-style: italic;
  font-weight: 400;
  font-display: swap;
  src: url("theme/assets/alegreya-italic-400-latin.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
@font-face {
  font-family: "Alegreya SC";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("theme/assets/alegreya-sc-500-cyrillic.woff2") format("woff2");
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
}
@font-face {
  font-family: "Alegreya SC";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("theme/assets/alegreya-sc-500-latin.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

/* ---------- Анимации ---------- */

/* Буквы поднимаются над полем ввода и расплываются */
@keyframes khazar-forget {
  0%   { background-position: 0 0, 0 0; }
  100% { background-position: 0 -240px, 180px -480px; }
}

/* ---------- Типографика ---------- */
.tavo-bubble-content,
.tavo-composer-input {
  font-family: "Alegreya", "Noto Serif", Georgia, serif;
}

.tavo-message-content {
  line-height: 1.6;
}

.tavo-message-content::selection,
.tavo-message-content *::selection {
  background: rgba(201, 174, 116, 0.3);
  color: inherit;
}

/* ---------- Персонаж: статья словаря ---------- */
.tavo-bubble {
  border-radius: 2px;
}

/* По умолчанию (и пока ответ пишется) — статья «Атех» из Красной книги.
   Первый слой фона — вкладка-указатель с буквой на правом краю, как в старых словарях */
.tavo-character-bubble {
  --book: #B5574C;
  --book-rgb: 181, 87, 76;
  --entry: "Ateh  ·  The Red Book";
  background-color: rgba(23, 21, 19, 0.93);
  background-image:
    url("theme/assets/tab-red-a.png"),
    linear-gradient(to bottom, rgba(var(--book-rgb), 0.1), rgba(var(--book-rgb), 0) 140px);
  background-size: 18px 30px, auto;
  background-repeat: no-repeat, no-repeat;
  background-position: right 0 top 12px, 0 0;
  border: 1px solid rgba(201, 174, 116, 0.12);
  border-left: 3px solid rgba(var(--book-rgb), 0.75);
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.55), inset 0 0 30px rgba(0, 0, 0, 0.3);
  padding: 14px 34px 14px 18px;
}

/* Заглавное слово статьи и книга */
.tavo-character-bubble-content::before {
  content: var(--entry);
  display: block;
  margin-bottom: 8px;
  padding-bottom: 5px;
  border-bottom: 1px solid rgba(var(--book-rgb), 0.3);
  font-family: "Alegreya SC", "Alegreya", Georgia, serif;
  font-size: 0.74em;
  letter-spacing: 0.1em;
  color: var(--book);
}

/* ---------- Вы: заметки читателя на полях ---------- */
.tavo-user-bubble {
  background-color: rgba(20, 26, 28, 0.9);
  border-right: 2px solid rgba(201, 174, 116, 0.4);
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.5);
}

.tavo-user-bubble-content {
  font-style: italic;
}

/* ---------- Имена и аватары ---------- */
.tavo-speaker-name {
  font-family: "Alegreya SC", "Alegreya", Georgia, serif;
  letter-spacing: 0.08em;
  color: #c9ae74;
}

.tavo-avatar {
  outline: 1px solid rgba(201, 174, 116, 0.5);
  outline-offset: -1px;
  filter: sepia(0.2) saturate(0.85);
}

/* ---------- Мысли, разделитель, вложения ---------- */
.tavo-message-reasoning {
  font-style: italic;
  color: #a3967e;
  border-left: 1px solid rgba(201, 174, 116, 0.3);
  padding-left: 10px;
}

.tavo-message-divider {
  height: 26px;
  border: 0;
  background: url("theme/assets/divider.svg") center / min(320px, 76%) auto no-repeat;
}

.tavo-message-attachments {
  outline: 3px solid rgba(23, 21, 19, 0.9);
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.5);
}

.tavo-action-bar-button,
.tavo-action-bar-button-group {
  background-color: rgba(16, 21, 23, 0.85);
  border-radius: 2px;
}

/* ---------- Поле ввода ---------- */
.tavo-composer {
  position: relative;
  padding-top: 34px;
}

/* По верхнему краю — три тонкие закладки трёх книг */
.tavo-composer-shell {
  background-color: rgba(16, 21, 23, 0.95);
  background-image: linear-gradient(to right,
    rgba(181, 87, 76, 0.7) 0 33.3%,
    rgba(127, 163, 131, 0.7) 33.3% 66.6%,
    rgba(205, 169, 86, 0.7) 66.6% 100%);
  background-size: 100% 2px;
  background-repeat: no-repeat;
  background-position: top left;
  border: 1px solid rgba(201, 174, 116, 0.28);
  border-radius: 2px;
  box-shadow: 0 -4px 20px rgba(0, 0, 0, 0.5);
}

/* Пока персонаж отвечает — над полем поднимаются и тают буквы */
:root:has(.tavo-composer-stop-icon) .tavo-composer::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: -14px;
  height: 44px;
  pointer-events: none;
  background-image: url("theme/assets/letters.png"), url("theme/assets/letters.png");
  background-size: 360px 240px, 540px 360px;
  background-repeat: repeat, repeat;
  opacity: 0.8;
  -webkit-mask-image: linear-gradient(to top, transparent 0%, #000 22%, #000 40%, transparent 100%);
  mask-image: linear-gradient(to top, transparent 0%, #000 22%, #000 40%, transparent 100%);
  animation: khazar-forget 18s linear infinite;
}

.tavo-composer-input {
  color: #e4dac4;
  caret-color: #c9ae74;
}

.tavo-composer-input::placeholder {
  color: #77766f;
  font-style: italic;
}

.tavo-composer-send-icon,
.tavo-composer-add-icon,
.tavo-composer-voice-icon,
.tavo-composer-stop-icon {
  filter: sepia(0.5) brightness(1.05);
}

@media (prefers-reduced-motion: reduce) {
  :root:has(.tavo-composer-stop-icon) .tavo-composer::before {
    animation: none;
  }
}

/* ---------- Книги и статьи (сгенерировано build.py) ---------- */
